import fs from 'node:fs';import {performance} from 'node:perf_hooks';import {critter,speciesColours,defaultStyle,bake} from '../art/generator.js';
const ids=['marten','stoat','meerkat','mole','hedgehog','dormouse','squirrel','flyingsquirrel'],style=defaultStyle();
fs.writeFileSync(new URL('./current-cpu-style.json',import.meta.url),JSON.stringify(style,null,2)+'\n');
for(const id of ids){
 await new Promise(r=>process.send({event:'start',id},r));
 const started=performance.now();const sprite=critter(id,3,0,style,'towards');
 const factory=()=>{const canvas={};canvas.getContext=()=>({createImageData:(w,h)=>({data:new Uint8ClampedArray(w*h*4)}),putImageData:img=>canvas.data=img.data});return canvas;};
 const colours=speciesColours(id,style);const {A,w,h}=bake(sprite,colours,style,style.cOutline,factory);
 const milliseconds=performance.now()-started;const dir=new URL('./art-pass/'+id+'/today-legend/',import.meta.url);fs.mkdirSync(dir,{recursive:true});
 fs.writeFileSync(new URL('albedo.rgba',dir),Buffer.from(A.data));
 fs.writeFileSync(new URL('capture.json',dir),JSON.stringify({id,w,h,milliseconds,level:3,frame:0,facing:'towards',style,colours,styleSelection:'defaultStyle() unchanged',artStyle:style.artStyle??null,pixel:style.pixel,outline:style.cOutline,kind:'plain albedo, no gear/woken/sleep/live lighting'},null,2)+'\n');
 await new Promise(r=>process.send({event:'done',id,w,h,milliseconds},r));
 if(milliseconds>=3000)process.exit(3);
}process.exit(0);

