import fs from 'node:fs';import {fork} from 'node:child_process';import {performance} from 'node:perf_hooks';
const start=performance.now(),manifest={started:new Date().toISOString(),results:[],status:'RUNNING',limitSpeciesMs:3000,limitProcessMs:30000};let speciesTimer,reason;const save=()=>fs.writeFileSync(new URL('./current-cpu-manifest.json',import.meta.url),JSON.stringify(manifest,null,2)+'\n');
const child=fork(new URL('./current-cpu-worker.mjs',import.meta.url),[],{stdio:['ignore','pipe','pipe','ipc']});let err='';child.stderr.on('data',b=>err+=b);const stop=r=>{reason=r;manifest.status=r;child.kill();save();};const outer=setTimeout(()=>stop('STOPPED_PROCESS_30S'),30000);
child.on('message',m=>{if(m.event==='start'){manifest.current=m.id;save();speciesTimer=setTimeout(()=>stop('STOPPED_SPECIES_3S:'+m.id),3000);}else if(m.event==='done'){clearTimeout(speciesTimer);manifest.results.push(m);delete manifest.current;save();}});
child.on('exit',(code,signal)=>{clearTimeout(outer);clearTimeout(speciesTimer);manifest.elapsedMs=performance.now()-start;manifest.status=reason??(code===0?'COMPLETE':'FAILED');manifest.exitCode=code;manifest.signal=signal;manifest.stderr=err;manifest.finished=new Date().toISOString();save();console.log(JSON.stringify(manifest));});
save();
